const M_LOGO = "data:image/png;base64,";
const M_HERO = "data:image/png;base64,";

import { useState } from "react";

const GS = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&family=DM+Mono:wght@400;500&family=Syne:wght@700;800&family=Playfair+Display:wght@700&display=swap');
    *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
    :root{
      --bg:#f0f0f6;--surface:#fff;--border:#e4e4ec;
      --text:#111118;--muted:#6b6b80;--faint:#9898b0;
      --accent:#6c5ce7;--accent-l:#f0eeff;
      --grad:linear-gradient(135deg,#6c5ce7,#00cec9);
      --shadow:0 1px 3px rgba(0,0,0,0.06),0 4px 16px rgba(0,0,0,0.06);
      --shadow-l:0 4px 24px rgba(0,0,0,0.10);
    }
    html,body,#root{min-height:100%;font-family:'Outfit',sans-serif;background:var(--bg);color:var(--text)}
    ::-webkit-scrollbar{width:4px}
    ::-webkit-scrollbar-thumb{background:#d0d0e0;border-radius:4px}
    @keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
    @keyframes orbit{from{transform:rotate(0deg) translateX(20px) rotate(0deg)}to{transform:rotate(360deg) translateX(20px) rotate(-360deg)}}
    .gtext{background:var(--grad);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
    .tab{padding:8px 18px;border-radius:9px;font-size:13px;font-weight:600;cursor:pointer;border:none;font-family:'Outfit',sans-serif;transition:all 0.15s;color:var(--muted);background:transparent}
    .tab.on{background:var(--surface);color:var(--accent);box-shadow:var(--shadow);border:1.5px solid var(--border)}
    .tab:hover:not(.on){color:var(--text)}
    .pill{display:inline-flex;align-items:center;padding:3px 10px;border-radius:20px;font-size:11px;font-weight:700;letter-spacing:0.03em}
    .pill-pro{background:var(--grad);color:#fff}
    .pill-free{background:var(--accent-l);color:var(--accent);border:1px solid rgba(108,92,231,0.2)}
    .card{background:#fff;border:1.5px solid var(--border);border-radius:14px;box-shadow:var(--shadow)}
    .od{width:5px;height:5px;border-radius:50%;position:absolute;top:50%;left:50%;margin:-2.5px;animation:orbit 2.5s linear infinite}
  `}</style>
);

const Mascot = ({ size = 32, hero = false }) => (
  <img src={hero ? M_HERO : M_LOGO} width={size} height={size}
    style={{ objectFit:"contain", display:"block", flexShrink:0 }} />
);

