/* ─── Phone Preview ─── */
const Phone = ({ t }) => {
  const isDark = t.pageText === "#fff" || t.pageText.startsWith("rgba");
  const isGradBg = t.bg.startsWith("linear");
  const isGradBtn = t.btnBg && t.btnBg.startsWith("linear");
  const fontMap = {
    "Outfit":"'Outfit',sans-serif",
    "Syne":"'Syne',sans-serif",
    "Playfair Display":"'Playfair Display',serif",
    "DM Mono":"'DM Mono',monospace"
  };
  const ff = fontMap[t.font] || "'Outfit',sans-serif";
  const demoLinks = ["Il mio sito","Blog & Articoli","Assistenza PC","TimbroSmart"];

  return (
    <div style={{
      width:160, borderRadius:28, overflow:"hidden", flexShrink:0,
      background: isGradBg ? undefined : t.bg,
      backgroundImage: isGradBg ? t.bg : undefined,
      boxShadow:"0 20px 48px rgba(0,0,0,0.2),0 2px 8px rgba(0,0,0,0.1)",
      border:"1px solid rgba(255,255,255,0.08)"
    }}>
      {/* Notch */}
      <div style={{display:"flex",justifyContent:"center",padding:"9px 0 5px",background:"rgba(0,0,0,0.18)"}}>
        <div style={{width:38,height:5,borderRadius:3,background:"rgba(255,255,255,0.15)"}}/>
      </div>
      {/* Body */}
      <div style={{padding:"14px 11px 18px",fontFamily:ff}}>
        {/* Avatar */}
        <div style={{textAlign:"center",marginBottom:12}}>
          <div style={{
            width:50,height:50,borderRadius:"50%",margin:"0 auto 7px",
            display:"flex",alignItems:"center",justifyContent:"center",overflow:"hidden",
            border:`2.5px solid ${t.ring}`,
            boxShadow:`0 4px 14px ${t.ring}40`,
            background:t.ring+"20"
          }}>
            <Mascot size={46} hero />
          </div>
          <div style={{color:t.pageText,fontSize:11.5,fontWeight:700,fontFamily:ff}}>DanyWolf</div>
          <div style={{color:t.pageBio,fontSize:9,marginTop:2}}>IT Tech · Developer</div>
          {/* Social icons */}
          <div style={{display:"flex",justifyContent:"center",gap:5,marginTop:7}}>
            {["instagram","youtube","github"].map(s=>(
              <div key={s} style={{
                width:20,height:20,borderRadius:"50%",
                background:t.socialBg,
                display:"flex",alignItems:"center",justifyContent:"center"
              }}>
                <img
                  src={`https://cdn.simpleicons.org/${s}/${t.socialIcon}`}
                  width={10} height={10}
                  style={{objectFit:"contain"}}
                  onError={e=>{ e.target.style.opacity=0; }}
                />
              </div>
            ))}
          </div>
        </div>
        {/* Links */}
        {demoLinks.map((l,i)=>{
          const isMain = i===0;
          const btnBg = isMain
            ? (isGradBtn ? t.btnBg : t.btnBg)
            : t.btnStyle==="outline" ? "transparent"
            : t.btnStyle==="glass" ? (isDark?"rgba(255,255,255,0.08)":"rgba(0,0,0,0.04)")
            : isDark ? "rgba(255,255,255,0.07)" : "rgba(0,0,0,0.04)";
          const btnColor = isMain ? t.btnText
            : t.btnStyle==="outline" ? t.btnText
            : t.btnStyle==="glass" ? t.pageText
            : t.pageText;
          return (
            <div key={i} style={{
              marginBottom:6, padding:"8px 10px",
              borderRadius:t.btnRadius,
              textAlign:"center", fontSize:9.5, fontWeight:700,
              fontFamily:ff,
              background:isMain?(isGradBtn?undefined:btnBg):btnBg,
              backgroundImage:isMain&&isGradBtn?t.btnBg:undefined,
              color:btnColor,
              border:t.btnStyle==="outline"?`1.5px solid ${t.ring}`:"none",
              boxShadow:isMain&&t.btnStyle==="shadow"?`0 4px 12px ${t.ring}40`:"none"
            }}>{l}</div>
          );
        })}
        {/* Footer */}
        <div style={{textAlign:"center",marginTop:8,display:"flex",alignItems:"center",justifyContent:"center",gap:4}}>
          <Mascot size={9}/>
          <span style={{fontSize:7.5,color:t.pageBio}}>CosmoLink</span>
        </div>
      </div>
    </div>
  );
};

/* ─── THEMES ─── */
const ThemeShowcase = () => {
  const [sel, setSel] = useState(null);
  const [filter, setFilter] = useState("Tutti");
  const list = filter==="Tutti" ? THEMES : filter==="Free" ? THEMES.filter(t=>t.free) : THEMES.filter(t=>!t.free);

  return (
    <div>
      <div style={{display:"flex",alignItems:"flex-end",justifyContent:"space-between",flexWrap:"wrap",gap:12,marginBottom:28}}>
        <div>
          <h2 style={{fontWeight:800,fontSize:26,letterSpacing:"-0.02em",marginBottom:6}}>Temi predefiniti</h2>
          <p style={{color:"var(--muted)",fontSize:14}}>10 temi curati — 4 gratis, 6 PRO. Clicca un tema per i dettagli.</p>
        </div>
        <div style={{display:"flex",gap:4,background:"#fff",border:"1px solid var(--border)",borderRadius:12,padding:4}}>
          {["Tutti","Free","PRO"].map(f=>(
            <button key={f} className={`tab ${filter===f?"on":""}`} onClick={()=>setFilter(f)}>{f}</button>
          ))}
        </div>
      </div>

      {/* Grid */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(300px,1fr))",gap:14,marginBottom:20}}>
        {list.map(t=>(
          <div key={t.slug} onClick={()=>setSel(sel?.slug===t.slug?null:t)}
            style={{
              background:"#fff", borderRadius:16, padding:18, cursor:"pointer",
              border: sel?.slug===t.slug ? "2px solid var(--accent)" : "2px solid var(--border)",
              boxShadow: sel?.slug===t.slug ? "0 4px 24px rgba(108,92,231,0.12)" : "var(--shadow)",
              transition:"all 0.18s", display:"flex", gap:14, alignItems:"flex-start"
            }}>
            {/* Mini phone */}
            <div style={{transform:"scale(0.68)",transformOrigin:"top left",width:109,height:192,flexShrink:0}}>
              <Phone t={t}/>
            </div>
            {/* Info */}
            <div style={{flex:1,paddingTop:2}}>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}>
                <span style={{fontWeight:800,fontSize:15}}>{t.name}</span>
                <span className={t.free?"pill pill-free":"pill pill-pro"}>{t.free?"FREE":"PRO"}</span>
              </div>
              <p style={{color:"var(--muted)",fontSize:12,lineHeight:1.6,marginBottom:10}}>{t.desc}</p>
              {/* Color swatches */}
              <div style={{display:"flex",gap:5,marginBottom:10}}>
                {[{v:t.bg,label:"BG"},{v:t.btnBg,label:"BTN"},{v:t.ring,label:"ACC"}].map(({v,label})=>(
                  <div key={label} title={label} style={{
                    width:24,height:24,borderRadius:7,
                    background:v.startsWith("linear")?undefined:v,
                    backgroundImage:v.startsWith("linear")?v:undefined,
                    border:"1px solid rgba(0,0,0,0.1)"
                  }}/>
                ))}
              </div>
              {/* Details */}
              {[["Font",t.font],["Bottone",t.btnStyle],["Radius",t.btnRadius+"px"]].map(([k,v])=>(
                <div key={k} style={{display:"flex",gap:8,fontSize:11,alignItems:"center",marginBottom:3}}>
                  <span style={{color:"var(--faint)",width:46,flexShrink:0}}>{k}</span>
                  <code style={{background:"var(--bg)",borderRadius:5,padding:"1px 8px",fontSize:10.5,fontWeight:500}}>{v}</code>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Expanded detail */}
      {sel && (
        <div style={{background:"#fff",borderRadius:18,padding:28,border:"2px solid var(--accent)",boxShadow:"0 8px 32px rgba(108,92,231,0.10)"}}>
          <div style={{display:"flex",gap:28,alignItems:"flex-start",flexWrap:"wrap"}}>
            <Phone t={sel}/>
            <div style={{flex:1,minWidth:240}}>
              <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:18}}>
                <h3 style={{fontWeight:800,fontSize:22}}>{sel.name}</h3>
                <span className={sel.free?"pill pill-free":"pill pill-pro"}>{sel.free?"FREE":"PRO"}</span>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
                {[
                  ["Sfondo", sel.bg.startsWith("linear")?"Gradiente":sel.bg],
                  ["Btn background", sel.btnBg.startsWith("linear")?"Gradiente":sel.btnBg],
                  ["Testo bottone", sel.btnText],
                  ["Stile bottone", sel.btnStyle],
                  ["Border radius", sel.btnRadius+"px"],
                  ["Testo pagina", sel.pageText],
                  ["Ring avatar", sel.ring],
                  ["Font", sel.font],
                ].map(([k,v])=>(
                  <div key={k} style={{background:"var(--bg)",borderRadius:10,padding:"10px 12px"}}>
                    <div style={{fontSize:10,color:"var(--faint)",fontWeight:700,marginBottom:4,letterSpacing:"0.04em"}}>{k.toUpperCase()}</div>
                    <div style={{display:"flex",alignItems:"center",gap:6}}>
                      {v.startsWith("#")&&<div style={{width:14,height:14,borderRadius:4,background:v,border:"1px solid rgba(0,0,0,0.1)",flexShrink:0}}/>}
                      <code style={{fontSize:11.5,fontFamily:"'DM Mono',monospace",fontWeight:500}}>{v}</code>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

